using NUnit.Framework;
using SaferAccessors.Tests;

namespace SaferAccessors.Analysis.Tests.Generators;

internal static class MethodAccessorGeneratorTests
{
	[Test]
	public static async Task GenerateWithInstanceMethodAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private int GetValue(string key) => 22;
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static class TestExtensions
			{
				extension(global::Test self)
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Method, Name = "GetValue")]
					public extern int GetValue(string key);
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}

	[Test]
	public static async Task GenerateWithStaticMethodAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private static int GetValue(string key) => 22;
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static class TestExtensions
			{
				extension(global::Test)
				{
					public static int GetValue(string key) =>
						(null as global::Test)!.GetValueMethod(key);
				}
				
				extension(global::Test self)
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.StaticMethod, Name = "GetValue")]
					private extern int GetValueMethod(string key);
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}
}